#!/usr/bin/env python3
"""Update the workspace around the existing, unchanged column model."""
from pathlib import Path

p = Path(__file__).resolve().parents[1] / 'viewer/index.html'
s = p.read_text()
a = s.index('<div class="iso"')
b = s.index('<p class="state-line"', a)
model = s[a:b]
head = '''<!doctype html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Мини 2 · Алиса</title><link href="https://fonts.googleapis.com/css2?family=Geist+Mono:wght@400;500;600&family=Manrope:wght@500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="style.css"></head><body><div class="bg" aria-hidden="true"></div><header class="top"><div class="brand"><span class="brand-mark">Я</span><div><p class="brand-name">Алиса<span class="brand-divider">/</span><span class="brand-model">Мини 2</span></p><p class="brand-sub">Локальная станция · оригинальная прошивка</p></div></div><div class="top-meta"><span id="conn" class="pill dim">Соединение…</span><span id="qemu" class="pill dim">QEMU…</span><span id="clock-live" class="pill mono"></span></div></header><main class="stage workspace-grid"><section class="device-wrap device-panel" aria-label="Мини 2"><div class="section-caption"><span>ВАША СТАНЦИЯ</span><span class="mono">ARM32 / QEMU</span></div>'''
services = [('platformd', 'Алиса', 'Основной процесс'), ('mediad', 'Медиасервис', 'Воспроизведение'), ('network', 'Сеть гостя', 'VirtIO Ethernet'), ('bluetooth', 'Bluetooth', 'Виртуальный адаптер'), ('sound', 'Звуковая карта', 'ALSA / VirtIO'), ('keymaster', 'Служба ключей', 'Защищённая подпись')]
rows = ''.join(f'<div class="service-item"><div><span class="service-name">{title}</span><span class="service-description">{desc}</span></div><span class="service-status" id="service-{key}"><i></i><span>Проверка</span></span></div>' for key, title, desc in services)
rest = '''<p class="state-line"><span class="state-indicator" id="stateIndicator"></span><span id="stateName">Ожидание состояния</span></p><div class="power-bar"><button id="powerToggle" class="power-primary" disabled><span class="power-symbol">⏻</span><span id="powerLabel">Подключение…</span></button><button id="rebootButton" class="reboot-button" disabled><span>↻</span>Перезапустить</button></div><p class="ctl-hint" id="ctlHint" role="status">Подключение к эмулятору…</p></section><section class="panel services-panel"><div class="panel-heading"><h2>Сервисы</h2><span class="live-badge"><i></i>LIVE</span></div><div class="service-grid">''' + rows + '''</div><p id="firmwareStatus" class="readiness-note">Получение состояния прошивки…</p></section><section class="panel console-panel"><div class="panel-heading"><div class="console-title"><h2>Консоль</h2><span class="console-subtitle">Вывод гостевой системы</span></div><div class="console-actions"><label class="autoscroll"><input type="checkbox" id="autoScroll" checked>Автопрокрутка</label><button id="downloadLog" class="quiet-button" title="Скачать журнал" aria-label="Скачать журнал">↓</button><button data-qemu="clear" class="quiet-button" title="Очистить журнал" aria-label="Очистить журнал">Очистить</button></div></div><div class="console-statusbar"><span><i></i>ttyAMA0</span><span class="mono">115200 · serial</span></div><pre id="bootlog" class="bootlog" aria-live="off"></pre></section><details class="panel events-panel"><summary><span>События</span><span class="event-counter" id="eventCount">0</span><span class="expand-icon">⌄</span></summary><ul id="events" class="events"></ul></details><footer class="workspace-footer"><span>Mini 2 · из резервной копии</span><span>Состояние поступает из гостевой системы</span></footer></main><div class="toast" id="toast" role="status" aria-live="polite"></div><script src="app.js"></script></body></html>'''
p.write_text(head + model + rest)
print('Workspace updated; device markup retained unchanged.')
